const std::unordered_map<std::string, uint64_t>& getRomSizes() {
    static std::unordered_map<std::string, uint64_t> map;
    if (map.empty()) {
        map.reserve(6719);
        for (const auto& entry : ROM_DATA) {
            map[entry.first] = entry.second;
        }
    }
    return map;
}
